double fa = f(a);
double fb = f(b);
double m = 0.5 * (a + b);
double fm = f(m);

auto simpson = [&](double fa, double fm, double fb, double a, double b) -> double {
    return (b - a) / 6.0 * (fa + 4.0 * fm + fb);
};

std::function<double(double, double, double, double, double, double)> adapt =
    [&](double a, double b, double eps, double fa, double fb, double fm) -> double {
        double m = 0.5 * (a + b);
        double lm = 0.5 * (a + m);
        double rm = 0.5 * (m + b);
        double flm = f(lm);
        double frm = f(rm);

        double left  = simpson(fa, flm, fm, a, m);
        double right = simpson(fm, frm, fb, m, b);
        double whole = simpson(fa, fm, fb, a, b);

        double delta = left + right - whole;
        if (std::abs(delta) <= 15.0 * eps) {
            return left + right + delta / 15.0;
        }
        return adapt(a, m, eps / 2.0, fa, fm, flm) +
               adapt(m, b, eps / 2.0, fm, fb, frm);
    };

return adapt(a, b, precision, fa, fb, fm);

